void display(unsigned val)
{
    std::cout << val << '\n';
}

void process_vector(const std::vector<unsigned>& data)
{
    auto minmax = std::minmax_element(data.begin(), data.end());
    unsigned min_value = *minmax.first;
    unsigned max_value = *minmax.second;
    display(min_value + (max_value - min_value) / 2);
}

int main()
{
    size_t n;
    std::cin >> n;
    std::vector<unsigned> arr(n);
    for (size_t i = 0; i < n; ++i)
        std::cin >> arr[i];

    process_vector(arr);
    return 0;
}
