import java.util.*;
import java.util.stream.*;

public class Main {
    public static void display(long val) {
        System.out.println(val);
    }

    public static void processVector(List<Long> data) {
        long minValue = Collections.min(data);
        long maxValue = Collections.max(data);
        display(minValue + (maxValue - minValue) / 2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        List<Long> arr = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            arr.add(scanner.nextLong());
        }
        processVector(arr);
        scanner.close();
    }
}
